  const current = parent._currentTab;
  const tabs = [["Home",IDS.Icon_Home],["Explore",IDS.Icon_Explore],["Library",IDS.Icon_Library]];
  for (const [name,id] of tabs) {
    const cell = figma.createFrame();
    cell.layoutMode="VERTICAL"; cell.primaryAxisAlignItems="CENTER"; cell.counterAxisAlignItems="CENTER";
    cell.itemSpacing=4; cell.fills=[]; cell.resize(142,80); cell.primaryAxisSizingMode="FIXED";
