const TEAL={r:0,g:0.761,b:0.796},SURFACE={r:0.1,g:0.11,b:0.125},GRAY={r:0.62,g:0.64,b:0.66},WHITE={r:1,g:1,b:1},STROKE={r:0.25,g:0.27,b:0.29};
function text(s,sz,w,c){const t=figma.createText();t.fontName={family:"Urbanist",style:w};t.characters=s;t.fontSize=sz;t.fills=[{type:"SOLID",color:c}];t.textAutoResize="WIDTH_AND_HEIGHT";return t;}
function rect(w,h,color,radius){const r=figma.createRectangle();r.resize(w,h);r.fills=color?[{type:"SOLID",color}]:[];if(radius)r.cornerRadius=radius;return r;}
async function icon(id,size){const n=await figma.getNodeByIdAsync(id);const inst=n.createInstance();if(size)inst.resize(size,size);return inst;}

const IDS={Icon_Back:"1:232",Icon_Grid:"1:241",Icon_Plus:"1:254"};

const f17 = page.findOne(n=>n.name==="17_Stats");
for(const c of [...f17.children].filter(c=>c.type!=="INSTANCE")) c.remove();
f17.appendChild(Object.assign(await icon(IDS.Icon_Back,24),{x:24,y:70}));
f17.appendChild(Object.assign(text("Top",20,"Bold",WHITE),{x:66,y:68}));
f17.appendChild(Object.assign(await icon(IDS.Icon_Grid,22),{x:344,y:70}));
f17.appendChild(Object.assign(await icon(IDS.Icon_Plus,22),{x:380,y:70}));
f17.appendChild(Object.assign(text("Past 30 Days",13,"Regular",GRAY),{x:24,y:108}));

const periods=["30 days","6 Months","1 Year","Lifetime"];
let px=24;
for(const p of periods){
  const sel=p==="30 days";
  const chip=figma.createFrame(); chip.layoutMode="HORIZONTAL"; chip.primaryAxisAlignItems="CENTER"; chip.counterAxisAlignItems="CENTER";
  chip.paddingLeft=14;chip.paddingRight=14;chip.paddingTop=8;chip.paddingBottom=8; chip.cornerRadius=20;
  chip.fills=[{type:"SOLID",color:sel?TEAL:SURFACE}]; if(!sel){chip.strokes=[{type:"SOLID",color:STROKE}];chip.strokeWeight=1;}
  chip.appendChild(text(p,12,"Medium",sel?{r:0,g:0.1,b:0.1}:WHITE));
  chip.x=px; chip.y=140; f17.appendChild(chip);
  px+=p.length*7+44;
}

const tabs=["Tracks","Artists","Albums"];
let tx=24;
for(const t of tabs){
  const sel=t==="Tracks";
  const tt=text(t,14,sel?"Bold":"Medium",sel?TEAL:GRAY);
  tt.x=tx; tt.y=190; f17.appendChild(tt);
  tx+=90;
}
const underline=rect(60,2,TEAL); underline.x=24; underline.y=214; f17.appendChild(underline);

const tracks=[["Swim","Atlas Drive"],["Time","Nolan Fray"],["Movies","Mira Vance"],["lowkey","Nika Rae"],["Hurt","Jinny Club"],["ILLUSION","Aeris"],["Neon Sting","Velvet Rose"]];
let ty=240;
let rank=1;
for(const [tn,an] of tracks){
  f17.appendChild(Object.assign(text("#"+rank,14,"Bold",GRAY),{x:24,y:ty+14}));
  const ph=rect(48,48,{r:0.2,g:0.21,b:0.23},10); ph.x=64; ph.y=ty; f17.appendChild(ph);
  f17.appendChild(Object.assign(text(tn,15,"Medium",WHITE),{x:124,y:ty+4}));
  f17.appendChild(Object.assign(text(an,12,"Regular",GRAY),{x:124,y:ty+24}));
  ty+=64;
  rank++;
}

"done17";

