function setNav(node, targetFrame, animation){
  if(!node||!targetFrame) return false;
  node.reactions = [{
    trigger:{type:"ON_CLICK"},
    actions:[{type:"NODE", destinationId: targetFrame.id, navigation: animation||"NAVIGATE", transition:null, preserveScrollPosition:false}]
  }];
  return true;
}

const results=[];
function tryLink(frame, matcher, target, label){
  if(!frame){results.push(label+": FRAME MISSING");return;}
  const node = frame.findOne(matcher);
  const ok = setNav(node, target);
  results.push(label+": "+(ok?"OK":"NODE NOT FOUND"));
}

